const customerId = String($('Kiểm tra Yêu cầu Chuyển NV1').item.json.customer_id ?? '');
const text = 'Dạ, hiện tại tư vấn viên CMS IntelliCAD đang bận nên chưa kịp phản hồi anh/chị. Em xin phép tiếp tục hỗ trợ thông tin CMS IntelliCAD trong lúc này ạ, anh/chị cứ tiếp tục nhắn cho em nhé!';
return { json: { data: [{ recipient: { id: customerId }, messaging_type: 'RESPONSE', message: { text } }] } };

const input = $('Lưu phản hồi AI - conversation_messages1').item.json;
const reply = String(input.output ?? input.text ?? '').trim();

if (!reply) {
  throw new Error('Không có nội dung phản hồi để gửi Facebook');
}

const source = $('Chuẩn bị đầu vào AI4').first().json;
const customerId = String(source.customer_id ?? '').trim();

if (!customerId) {
  throw new Error('Không tìm thấy customer_id để gửi Facebook');
}

const limit = 1900;
const parts = [];
let remaining = reply;

while (remaining.length > limit) {
  let splitAt = remaining.lastIndexOf('\n', limit);

  if (splitAt < Math.floor(limit * 0.6)) {
    splitAt = remaining.lastIndexOf(' ', limit);
  }

  if (splitAt < Math.floor(limit * 0.6)) {
    splitAt = limit;
  }

  const part = remaining.slice(0, splitAt).trim();

  if (part) {
    parts.push(part);
  }

  remaining = remaining.slice(splitAt).trim();
}

if (remaining) {
  parts.push(remaining);
}

return parts.map((text, index) => ({
  json: {
    data: [
      {
        recipient: { id: customerId },
        messaging_type: 'RESPONSE',
        message: { text }
      }
    ],
    part_index: index + 1,
    part_total: parts.length
  }
}));

