const httpFailed=Boolean($json.error),conversations=Array.isArray($json.data)?$json.data:[],conversation=conversations[0]||null,messages=Array.isArray(conversation?.messages?.data)?conversation.messages.data:[];
let anchorIndex=messages.findIndex(message=>String(message?.id||'')===customerMessageId),newerMessages=[],anchorFoundBy='none';
if(anchorIndex>=0){newerMessages=messages.slice(0,anchorIndex);anchorFoundBy='message_id';}else if(customerMessageTs>0){newerMessages=messages.filter(message=>{const ts=Date.parse(String(message?.created_time||''));return Number.isFinite(ts)&&ts>customerMessageTs;});anchorFoundBy='timestamp';}
const newerCustomerMessages=newerMessages.filter(message=>String(message?.from?.id||'')===customerId),staleCustomerEvent=!dbLatest||newerCustomerMessages.length>0;
const rawPageReplies=newerMessages.filter(message=>{const fromId=String(message?.from?.id||''),toIds=Array.isArray(message?.to?.data)?message.to.data.map(item=>String(item?.id||'')):[];return fromId===pageId&&(toIds.length===0||toIds.includes(customerId))&&String(message?.message||'').trim();});
const instantWindowMs=3000,instantPageReplies=rawPageReplies.filter(message=>{const ts=Date.parse(String(message?.created_time||''));return customerMessageTs>0&&Number.isFinite(ts)&&ts-customerMessageTs<=instantWindowMs;});
const knownBotReplies=rawPageReplies.filter(isKnownBot),eligiblePageReplies=staleCustomerEvent?[]:rawPageReplies.filter(message=>!instantPageReplies.includes(message)&&!knownBotReplies.includes(message));
