return {json:{...base,stale_customer_event:staleCustomerEvent,meta_check_ok:metaCheckOk,meta_http_failed:httpFailed,meta_conversation_id:String(conversation?.id||''),anchor_found_by:anchorFoundBy,anchor_message_found:anchorIndex>=0,newer_messages_count:newerMessages.length,newer_customer_message_exists:newerCustomerMessages.length>0,meta_page_replied:metaHumanReplied,human_reply_detected:humanReplyDetected,human_reply_message_id:String(latestPageReply?.id||''),human_reply_created_time:String(latestPageReply?.created_time||''),human_reply_text:String(latestPageReply?.message||''),human_reply_messages:humanReplyMessages,should_bot_reply_final:shouldBotReplyFinal,meta_debug:{page_id:pageId,customer_id:customerId,customer_message_id:customerMessageId,customer_message_timestamp_ms:customerMessageTs,checked_messages:messages.length,anchor_index:anchorIndex,raw_page_reply_count:rawPageReplies.length,known_bot_reply_count:knownBotReplies.length,page_reply_count:eligiblePageReplies.length,instant_page_reply_count:instantPageReplies.length,newer_customer_count:newerCustomerMessages.length,db_human_replied:dbHuman,db_message_is_latest:dbLatest,http_failed:httpFailed}}};

