  const pageId = String($('Chuẩn hóa tin nhắn5').item.json.page_id ?? 'unknown');
  throw new Error('CONVERSATION_UPSERT_FAILED: Không tìm thấy Facebook channel/chatbot IntelliCAD hợp lệ cho page_id=' + pageId);
}
