    .slice(1, -1)
    .split('|')
    .map(cell =>
      clean(
        cell
          .replace(/\*\*/g, '')
          .replace(/__/g, '')
      )
    )
    .filter(Boolean);
}


// ==========================================================
// 5. CHUYỂN MARKDOWN -> FORMAT MESSENGER
// ==========================================================

const lines = text.split(/\r?\n/);

const blocks = [];

let tableHeaders = null;
let tableRows = [];

function flushTable() {
  if (!tableRows.length) {
    tableHeaders = null;
    return;
  }

  const tableBlock = [];

  tableBlock.push('📊 SO SÁNH');

  for (const row of tableRows) {
    // Nếu có header tương ứng
    if (tableHeaders && tableHeaders.length === row.length) {
      const first = row[0];

      tableBlock.push('');
      tableBlock.push(`• ${first}`);

      for (let i = 1; i < row.length; i++) {
        if (!row[i]) continue;

        const label = tableHeaders[i] || `Thông tin ${i}`;

        tableBlock.push(`  - ${label}: ${row[i]}`);
      }
    } else {
      tableBlock.push(`• ${row.join(' — ')}`);
    }
  }

  blocks.push(tableBlock.join('\n').trim());

  tableHeaders = null;
  tableRows = [];
}


for (const rawLine of lines) {

  let line = clean(rawLine);

  // dòng trống
  if (!line) {
    flushTable();

    if (
      blocks.length &&
      blocks[blocks.length - 1] !== ''
    ) {
      blocks.push('');
    }

    continue;
  }

  // separator của markdown table
  if (isDivider(line)) {
    continue;
  }

  // Markdown table
  if (isTableRow(line)) {

    const cells = tableCells(line);

    if (!cells.length) {
      continue;
    }

    if (!tableHeaders) {
      tableHeaders = cells;
    } else {
      tableRows.push(cells);
    }

    continue;
  }

  flushTable();


  // ========================================================
  // Markdown Heading
  // ========================================================

  const headingMatch = line.match(/^#{1,6}\s+(.+)$/);

  if (headingMatch) {
    const title = clean(headingMatch[1]);

    blocks.push(`📌 ${title.toUpperCase()}`);
    continue;
  }


  // ========================================================
  // Bullet markdown
  // ========================================================

  line = line
    .replace(/^[-*+]\s+/, '• ')
    .replace(/^\d+[.)]\s+/, match => `${match.trim()} `);


  blocks.push(line);
}

flushTable();


// ==========================================================
// 6. GHÉP LẠI
// ==========================================================

text = blocks
  .join('\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();


// ==========================================================
// 7. CHUẨN HÓA PARAGRAPH
// Messenger nên ngắn, tránh khối chữ quá dài
// ==========================================================

const sourceParagraphs = text
  .split(/\n{2,}/)
  .map(p => p.trim())
  .filter(Boolean);

const readableParagraphs = [];


// ==========================================================
// Tách câu thông minh
// Không cắt:
// - số thập phân 12.5
// - extension .dwg
// - URL đã được bảo vệ
// ==========================================================

function splitSentences(paragraph) {

  let safe = paragraph

    // file extension
    .replace(
      /\.(dwg|dxf|dgn|dwf|dxb|dwt|svg|pdf|net)\b/gi,
      '__DOT__$1'
    )

    // decimal
    .replace(
      /(\d)\.(?=\d)/g,
      '$1__DECIMAL__'
    );

  const result =
    safe.match(/[^.!?]+(?:[.!?]+|$)/g)
      ?.map(v => v.trim())
      .filter(Boolean)
    ?? [safe];

  return result.map(v =>
    v
      .replace(/__DOT__(dwg|dxf|dgn|dwf|dxb|dwt|svg|pdf|net)/gi, '.$1')
      .replace(/__DECIMAL__/g, '.')
  );
}


// ==========================================================
// 8. CHIA ĐOẠN DÀI
// ==========================================================

const MAX_PARAGRAPH = 320;
const TARGET_PARAGRAPH = 250;

for (const paragraph of sourceParagraphs) {

  // Bullet/table đã dễ đọc -> giữ nguyên
  if (
    paragraph.length <= MAX_PARAGRAPH ||
    /^•/m.test(paragraph) ||
    /^📊/m.test(paragraph)
  ) {
    readableParagraphs.push(paragraph);
    continue;
  }

  const sentences = splitSentences(paragraph);

  let group = '';

  for (const sentence of sentences) {

    const candidate =
      group
        ? `${group} ${sentence}`
        : sentence;

    if (
      group &&
      candidate.length > TARGET_PARAGRAPH
    ) {
      readableParagraphs.push(group.trim());
      group = sentence;
    } else {
      group = candidate;
    }
  }

  if (group.trim()) {
    readableParagraphs.push(group.trim());
  }
}


// ==========================================================
// 9. STYLE THEO NGỮ NGHĨA
// Chỉ thêm icon khi thực sự hữu ích
// ==========================================================

function getSectionIcon(paragraph) {

  const p = paragraph.toLowerCase();

  if (
    /báo giá|mức giá|đơn giá|chiết khấu|ưu đãi|khuyến mãi/.test(p)
  ) {
    return '💰';
  }

  if (
    /so sánh|khác nhau|khác biệt|versus|\bvs\b/.test(p)
  ) {
    return '📊';
  }

  if (
    /tính năng|hỗ trợ|định dạng|tương thích|dwg|dxf|dgn/.test(p)
  ) {
    return '💡';
  }

  if (
    /dùng thử|bản trial|bản demo|link tải|tải xuống/.test(p)
  ) {
    return '🔗';
  }

  if (
    /số điện thoại|email|họ tên|thông tin liên hệ|liên hệ/.test(p)
  ) {
    return '📌';
  }

  if (
    /lưu ý|quan trọng|chú ý/.test(p)
  ) {
    return '⚠️';
  }

  return '';
}


// ==========================================================
// 10. KHÔNG NHỒI QUÁ NHIỀU EMOJI
// ==========================================================

let iconCount = 0;
const MAX_ICONS = 4;

const styledParagraphs = readableParagraphs.map(
  (paragraph, index) => {

    let value = paragraph.trim();

    if (!value) {
      return '';
    }

    // Đã có emoji đầu dòng -> không thêm
    if (/^[\p{Extended_Pictographic}]/u.test(value)) {
      return value;
    }

    // Greeting đầu tiên không cần icon
    if (
      index === 0 &&
      /^(dạ|chào|xin chào|em chào)/i.test(value)
    ) {
      return value;
    }

    if (iconCount >= MAX_ICONS) {
      return value;
    }

    const icon = getSectionIcon(value);

    if (icon) {
      iconCount++;
      return `${icon} ${value}`;
    }

    return value;
  }
);


// ==========================================================
// 11. LÀM NỔI BẬT CÁC BULLET QUAN TRỌNG
